  .legend-line {
    width: 28px;
    height: 3px;
    border-radius: 2px;
  }
  .legend-dash {
    width: 28px;
    height: 0;
    border-top: 2px dashed;
  }
  .legend-rect {
    width: 28px;
    height: 12px;
    border-radius: 3px;
  }

  /* ===== GROWTH TABLE ===== */
  .growth-table-wrap {
    margin-top: 24px;
    overflow-x: auto;
  }
  .growth-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 14px;
  }
  .growth-table th {
    text-align: left;
    padding: 10px 14px;
    font-weight: 600;
    color: #8B9AAF;
    border-bottom: 1px solid rgba(26, 68, 114, 0.5);
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }
  .growth-table td {
    padding: 10px 14px;
