    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 28px;
  }
  .column-card {
    background: rgba(13, 40, 71, 0.5);
    border: 1px solid rgba(26, 68, 114, 0.4);
    border-radius: 16px;
    padding: 28px;
