  .inflation-col.global .inflation-dot { background: #6CAAE0; }
  .inflation-col.us .inflation-dot { background: #D4A84B; }
  .inflation-point p {
    font-size: 14px;
    color: #C8D6E5;
    line-height: 1.4;
  }

  /* ===== POLICY TIMELINE ===== */
  .policy-section {
    background: rgba(13, 40, 71, 0.5);
    border: 1px solid rgba(26, 68, 114, 0.4);
