    align-items: center;
    justify-content: center;
    font-size: 13px;
    font-weight: 700;
    color: #FFFFFF;
    position: relative;
    z-index: 1;
  }
  .policy-step:last-child .policy-dot {
    background: #D4A84B;
    border-color: #E8C06A;
    color: #002244;
  }
  .policy-period {
    font-size: 13px;
    font-weight: 600;
    color: #6CAAE0;
    margin-top: 12px;
    margin-bottom: 4px;
  }
  .policy-step:last-child .policy-period { color: #D4A84B; }
  .policy-desc {
    font-size: 14px;
    color: #C8D6E5;
    line-height: 1.45;
  }

  /* ===== THEMES GRID ===== */
  .themes-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
  }
  .theme-card {
    background: rgba(13, 40, 71, 0.5);
    border: 1px solid rgba(26, 68, 114, 0.35);
    border-radius: 12px;
    padding: 22px 20px;
    display: flex;
    align-items: center;
    gap: 16px;
  }
  .theme-icon {
    flex-shrink: 0;
    width: 44px;
    height: 44px;
    background: rgba(108, 170, 224, 0.1);
